// Builds Foxden/Data/Catalog.lua: the game data every Foxden user gets built in, so the addon works
// on its own from CurseForge (no companion app, no website). It's the website's export with only
// general game data kept: recipes and their materials and costs, item and quest rewards, dungeon
// quests, boss loot tables, class trainer lists, skill ranges, known bosses, rare respawn timers and
// an auction price snapshot. Nothing guild-private: no crafter names, wishlists, orders, tips, notes,
// events, run splits or the website's address.
//   node tools/build-catalog.mjs   on this Mac: reads INGEST_KEY and SITE_URL from site/.env.local
//   In the weekly GitHub job: FOXDEN_SITE_URL, FOXDEN_EXPORT_KEY and CATALOG_OUT come from the environment.
import { existsSync, readFileSync, writeFileSync } from "node:fs";

const envFile = new URL("../site/.env.local", import.meta.url);
const env = existsSync(envFile) ? Object.fromEntries(readFileSync(envFile, "utf8")
  .split("\n").map(l => l.match(/^([A-Z_]+)=(.*)$/)).filter(Boolean).map(m => [m[1], m[2].replace(/^"|"$/g, "")])) : {};
const SITE = process.env.FOXDEN_SITE_URL || env.SITE_URL || env.NEXT_PUBLIC_SITE_URL;
const KEY = process.env.FOXDEN_EXPORT_KEY || env.INGEST_KEY;
if (!SITE || !KEY) throw new Error("Set FOXDEN_SITE_URL and FOXDEN_EXPORT_KEY (or SITE_URL and INGEST_KEY in site/.env.local)");
const OUT = process.env.CATALOG_OUT ? new URL(`file://${process.env.CATALOG_OUT}`) : new URL("../Foxden/Data/Catalog.lua", import.meta.url);
const res = await fetch(`${SITE.replace(/\/$/, "")}/api/export`, { headers: { Authorization: `Bearer ${KEY}` } });
if (!res.ok) throw new Error(`export: ${res.status}`);
const data = await res.json();

const KEEP = ["v", "at", "house", "pricesAt", "free", "quests", "mats", "matsByName", "costs", "rewards", "ah", "loot", "skill", "trainers", "bosses", "rares"];
const out = { bundled: true };
for (const k of KEEP) if (data[k] !== undefined) out[k] = data[k];
// rare sightings carry who saw them ([lastKill, lastSeen, minMinutes, maxMinutes, killedBy, seenBy]): keep the times only
if (out.rares) for (const id of Object.keys(out.rares)) { const r = out.rares[id]; if (Array.isArray(r)) out.rares[id] = [r[0], r[1], r[2], r[3], "", ""]; }

// the same Lua writer as the companion (whole-number keys become Lua numbers)
function toLua(v) {
  if (v === null || v === undefined) return "nil";
  if (typeof v === "number") return Number.isFinite(v) ? String(v) : "nil";
  if (typeof v === "boolean") return v ? "true" : "false";
  if (typeof v === "string") return '"' + v.replace(/\\/g, "\\\\").replace(/"/g, '\\"').replace(/\n/g, "\\n").replace(/\r/g, "") + '"';
  if (Array.isArray(v)) return "{" + v.map(toLua).join(",") + "}";
  return "{" + Object.entries(v).map(([k, x]) => `[${/^-?[1-9]\d{0,14}$/.test(k) ? k : toLua(k)}]=${toLua(x)}`).join(",") + "}";
}
const lua = `-- Built-in game data (recipes, materials, rewards, dungeon quests, loot tables, trainer lists, prices
-- from ${new Date(out.pricesAt * 1000).toISOString().slice(0, 10)}). Generated by tools/build-catalog.mjs from the guild website's export,
-- general game data only. The companion app's Data/SiteData.lua takes over when it's there.
-- Sources: Blizzard Entertainment (game data API), QuestieDB (GPLv3), ForeverDungeonRoutes (MIT).
FoxdenCatalog = ${toLua(out)}
`;
writeFileSync(OUT, lua);
console.log(`Catalog.lua: ${(lua.length / 1024).toFixed(0)} KB, ${Object.keys(out).length} parts`);
